Pseudocode for prefetch intent emission (CUDA-ish pseudo):

// control kernel (lightweight)
if (!page_resident(pageId)) {
  if (!prefetch_queue.push_if_space(pageId)) {
    // fallback: synchronous fetch using async copy but limit concurrency
    async_fetch_page(pageId);
  }
}

// background cooperative worker (persistent CTA)
while (work_remaining) {
  id = prefetch_queue.pop();
  if (id) {
    async_fetch_page(id); // cudaMemcpyAsync into pinned staging buffer -> device page frame
    update_page_table(id, resident=true);
  }
}
